Here's a C++ function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(#*(.*?)\*(.*?)(\n.*)");
    std::smatch match;
    while (std::regex_search(html, match, re)) {
        html = match[1] + "<b>" + match[2] + "</b>" + match[3];
    }
    return html;
}

int main() {
    std::string markdown = "#This is a header\nThis is a paragraph of bold text";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to match Markdown headings and replace them with HTML tags. The regular expression `(#*(.*?)\*(.*?)(\n.*)` matches the pattern `#This is a header*This is a paragraph of bold text` and replaces it with `<b>This is a header</b> This is a paragraph of bold text</b>`.

